if(!function_exists("getParentSection_678_3")) {

    function getParentSection_678_3($sectionId)
    {
        $sectionRes = CIBlockSection::GetByID($sectionId);

        if ($section = $sectionRes->GetNext()) {
            $parentSectionId = $section['IBLOCK_SECTION_ID'];

            if ($parentSectionId) {
                $parentSectionRes = CIBlockSection::GetByID($parentSectionId);
                if ($parentSection = $parentSectionRes->GetNext()) {
                    return $parentSection;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        } else {
            return false;
        }

        return false;
    }
}

